```latex
Let $\bb N$ be the set of all non-negative integers and $\bb R$ be the set of all real numbers. Additionally, we use $\mathbb{R}_{\geq 0}$ to represent the set of all non-negative real numbers. For any $n\in \bb N$, use $[n]$ to denote the set $\set{1,2,\dots,n}$. In this paper, unless otherwise specified, our logarithms are defined as natural logarithms with base $e$. For any $a\geq 1$, let $\-{ilog}^{(0)}(a)=a$ and $\-{ilog}^{(k)}(a)$ be the \emph{iterated logarithm} of order $k$ for integer $k\ge 1$, that is, $\-{ilog}^{(k)}(a)=\max\set{\log\tp{\-{ilog}^{(k-1)}(a)}, 1}$.

In the problem of multi-armed bandit (MAB), the player is given a set of $n$ arms, denoted as $[n]$. A $T$-round decision game will be conducted as follows: in each round $t\in[T]$, \begin{itemize}
    \item the player picks an arm $A_t\in[n]$ to pull based on the information observed in so far;
    \item the environment choose a reward vector $r_t\in [0,1]^n$;
    \item the player observes and gains reward of the chosen arm $r_t(A_t)$.
\end{itemize}

The reward can be given \emph{stochastically} or \emph{adversarially}. In the stochastic environment considered in this work, there is a fixed distribution $\+D_i$ of mean $\mu_i$ for each $\a_i$. In each round, $r_t(i)$ is independently  drawn from this distribution. 
The best arm, $\a^*$, refers to the arm with the largest mean reward. The player's objective is to minimize the difference between the cumulative reward of the best arm and the player's own cumulative reward. That is, the player aims to design an algorithm $\+A$ to minimize the expected regret
\[
    R(T,\+A) = \E{\sum_{t=1}^T \mu_{\a^*} - \mu_{A_t}}.
\]
We also write $R(T,\+A)$ as $R(T)$ when $\+A$ is clear from the context.

In the streaming MAB problem, the $n$ arms arrive in a stream, and available arms are stored in the memory $\+M$ which has a maximum capacity of $m$ arms for some $m\le n$.

In this work, we consider a general setting with $P$ passes ($P\geq 1$). In each pass, the $n$ arms will pass through the stream one time.

An algorithm is allowed to have its own randomness. We use $\Pr[H]{\cdot}$ or $\E[H]{\cdot}$ to denote the probability or expectation when the input instance is $H$, where the randomness comes from both the input instance and the algorithm itself.

We divide the $T$ rounds of the game into two phases, the \emph{exploration phase} and \emph{exploitation phase}. The rounds \emph{before} the arrival of the last arm in the last pass constitute the phase of exploration, and the remaining rounds form the phase of exploitation.

\begin{algorithm}[h]
    \caption{A subroutine using online stochastic mirror descent to find a good arm}
    \label{algo:bandit-subroutine}
    \Input{a set of arms $\+S$ and the number of rounds $L$}\\
    \Output{an arm in $\+S$}
\begin{algorithmic}[1]
    \Procedure{\textsc{FindBest}}{$\+S,L$}
    \State Run \Call{MirrorDescent}{$\+S,L$} 
    \ForAll{$\a_i\in\+S$}
        \State $T_i\gets$ the number of times $\a_i$ has been sampled in the \Call{MirrorDescent}{} routine
    \EndFor
    \State Sample an arm $\a'\in \+S$ with law $\Pr{\a'=\mbox{the }i\mbox{-th arm}}=\frac{T_i}{L}$
    \State \Return $\a'$
    \EndProcedure
\end{algorithmic}
\end{algorithm}

\begin{lemma}\label{lem:ub-bandit-subroutine-simple}
    Let $\a^*_{\+S}$ be the optimal arm in $\+S$. What ever the input arms are, \Cref{algo:bandit-subroutine} guarantees that $\E{\mu_{\a^*_{\+S}} - \mu_{\a'}}\leq \sqrt{\frac{2\abs{\+S}}{L}}$.
\end{lemma}

Let $\-{BAI}(\eps,\delta)$ be an $(\eps, \delta)$-PAC streaming algorithm. Let $\+S\subseteq[n]$ be the set of arms that are input into $\-{BAI}(\eps,\delta)$. Let $\a^*_{\+S}$ be the optimal arm in $\+S$.

\begin{proposition}\label{prop:BAIblackbox}
    There exists a $(\eps,\delta)$-PAC streaming algorithm $\-{BAI}(\eps,\delta)$ with input arm set $\+S$ satisfying:
    \begin{enumerate}
        \item \textbf{Correctness}: $\-{BAI}(\eps,\delta)$ returns an arm $\k\in \+S$ such that $\E{\mu_{\a^*_{\+S}} - \mu_{\k}}\leq \eps$.
        \item \textbf{Storage}: $\-{BAI}(\eps,\delta)$ uses a memory size of at most $m$. Furthermore, there is one position among $m$ memory slots specifically allocated for storing the newly arrived arm. 
        \item \textbf{Benchmark arm}: $\-{BAI}(\eps,\delta)$ maintains a good arm $\a^*_{\!{max}}$ in memory during its process and $\a^*_{\!{max}}$ always satisfies $\E{\mu_{k_1}-\mu_{\a^*_{\!{max}}}}\leq \eps$, where $k_i$ is the $i$-th arm fed into $\-{BAI}(\eps,\delta)$.
        \item \textbf{Regret guarantee}: When $\+S$ is a random set and for every $i$, $\mu-\E{\mu_{k_i}}\leq \eps'$ for some fixed numbers $\mu\in(0,1),\eps'\in(\eps,1)$, 
                the expected regret generated by the $\-{BAI}(\eps,\delta)$ process with regard to an arm with mean $\mu$ is bounded by $O\tp{\frac{n\eps'}{\eps^2}\tp{\log\tp{\frac{1}{\delta}} + \-{ilog}^{(m-1)}(n)}}$. \footnote{Here the arm with mean $\mu$ does not have to be in $\+S$. Let $\tau$ be the sample complexity of the BAI algorithm, $A_t$ be the index of arm played in round $t$ for $t\in[\tau]$. This regret is defined as $\E{\sum_{t=1}^{\tau} \mu-\mu_{A_t}}$. This expectation includes the randomness of the instance, the algorithm and random set $\+S$.}
    \end{enumerate}
\end{proposition}

The memory size is $m$ where $2\leq m< \frac{8n}{9}$. Let $r=\min\set{\lfloor\log^*(n+1)\rfloor, m-1}$. Define $\lambda_p=\frac{2^{P-p+1}-1}{2^{P+1}-1}$ for $p\in[P]$ and choose $\delta=\frac{1}{4}$. Let $\a^*$ be the optimal arm in stream. Let $\set{\eps_p}_{p\in[P]\cup \set{0}}$ be some parameters to be set later. 

Set the following parameters:
\begin{itemize}
        \item $\eps_0=1$ and $\eps_p={2^{P-p+1}\cdot \tp{\frac{(n+1)\cdot \-{ilog}^{(m-1)}(n+1)}{T}}^{\frac{1-\lambda_p}{2}}}$ for each $p\in[P]$;
    \item  for each $p\in[P]$, set $s^{(p)} = \ceil{\frac{2^{5}}{\eps_p^2}\tp{\log \frac{2^{3}\cdot\-{ilog}^{(r-1)}(n+1)}{\delta}}}$, which is the sample times of the $\textsc{FindBest}$ subroutine in pass $p$.
\end{itemize}

\begin{algorithm}[ht]
    \caption{Multi-pass algorithm for MAB with small memory ($m\le \frac{8n}{9}$)}
    \label{algo:small-m}
    \Input{number of passes $P$, time horizon $T$}
\begin{algorithmic}[1]
    \State let $\k_0$ be the first arm in pass $1$
    \For{$p=1,2,\dots,P$}
        \State initialize a \Call{BAI}{$\eps_p,\delta$} instance and feed $\k_{p-1}$ into \Call{BAI}{$\eps_p,\delta$}
        \For{ each arriving arm $\a_i$}\label{line: new arm}
        \State read $\a_i$ into memory \label{line:readin}
        \State $a_i^{(p)}\gets$\Call{FindBest}{$\set{\a^*_{\!{max}}, \a_i}$,$s^{(p)}$}\label{line:callfindbest}
        \If{$a_i^{(p)}\neq \a_i$}
            \State go to Line~\ref{line: new arm}
        \Else
            \State feed $\a_i$ into \Call{BAI}{$\eps_p,\delta$}
            \State update $\a^*_{\!{max}}$ \Comment{$\a^*_{\!{max}}$ is the good arm maintained by \Call{BAI}{$\eps_p,\delta$}}
        \EndIf
        \EndFor
    \State $\k_p\gets$\Call{BAI}{$\eps_p,\delta$} 
    \EndFor
    \State pull $\k_P$ until the game ends
\end{algorithmic}
\end{algorithm}

\begin{lemma}[Lemma~\ref{lem:ub-bandit-subroutine-simple} restated]\label{lem:findbest-perform}
Let $\a^*_{\+S}$ be the optimal arm in $\+S$. Then the $\textsc{FindBest}$ subroutine (\Cref{algo:bandit-subroutine}) guarantees that $\E{\mu_{\a^*_{\+S}} - \mu_{\a'}}\leq \sqrt{\frac{2\abs{\+S}}{L}}$, where $\a'$ is the arm returned by \Cref{algo:bandit-subroutine}.
\end{lemma}
